float smax( float a, float b, float k )
{
    float h = max(k-abs(a-b),0.0);
    return max(a, b) + h*h*0.25/k;
}



float cubeGrid3d(vec3 p, float s, float tc) {

    float ss = 1.41;
    s *= ss;

    float s2 = s/7.;
    float s3 = s2-.08*S(1., 2., tt);

    float g = s2*2.0;

    float N = 3.;

    float idW = pModInterval1(p.z, g, -N, N);
    float idH = pModInterval1(p.y, g, -N, N);
    float idZ = pModInterval1(p.x, g, -N, N);

    float sm = mix(1., 0.04, SIN(idH+2.*tt+4.5)*S(1., 2.5, iTime)*S(13.5, 12.,iTime) +
                             SIN(idW+2.*tt+4.5)*S(14.5, 16., iTime)*S(27.5, 27.,iTime) +
                             SIN(idZ-2.*tt+4.5)*S(28., 30.5, iTime)*S(42., 40.5, iTime)
    );

    vec3 ps = vec3(idW, idH, idZ);

    ps.xy += vec2(sin(4.*tt));
    ps.z += cos(5.*tt);

    sm = mix(1., 0.04, SIN(idW*(.2, 4., SIN(tt))+idH*mix(1.1, .1, SIN(.4*tt))+idZ*mix(.2, .5, SIN(.8*tt+PI)) + 2.*tt+4.)*S(1., 2.5, iTime));

    float d = box(p, vec3(s3*sm))-.05*sm;

    return d*mix(.4, 1., sm);
}


float caps( vec3 p, float h, float r )
{
  p.y -= clamp( p.y, 0.0, h );
  return length( p ) - r;
}

float map(vec3 p) {   

    p.y += 2.;
    p.xy = vec2(atan(p.y, p.x)*2.8, length(p.xy)*1.5);
    p.x = sabsk(p.x, .5);
    float d = 1e4;

    float n = smoothNoise21(p.xy*.2-tt*.4);
    float n2 = smoothNoise21(p.xy*.2-tt*.2+5.);
    p.xy *= rot(.5+0.05*sin(tt*.4));

    p.z += 2.*n;

    d = box(p, vec3(1000, 1000, .7));

    p.x -= .2*tt + .2*sin(.5*tt);
    p.y += .2*sin(p.z*5.+.5*tt);
    pMod(p.xy, vec2(.4));
   // p.z +=  2.*exp(-2.*length(p.xy));

    g_p = p;
    p.yz = p.zy;
    p.y += 3.78-3.*n2;
      //  p.xz += vec2(sin(p.y*14.+5.*tt+n), cos(p.y*14.+5.*tt+n))*.1*S(-1.,10., p.y);
    d = smin(d, caps(p, 4.*mix(.8, 1., n2),1.*(.8-.7*sin(n2+tt))*S(-1.4 - 3.*n,7., p.y)), 1.2);

    return d*.5;

}


vec3 getNormal(vec3 p) {

    vec2 eps = vec2(0.001, 0.0);
    return normalize(vec3(map(p + eps.xyy) - map(p - eps.xyy),
                          map(p + eps.yxy) - map(p - eps.yxy),
                          map(p + eps.yyx) - map(p - eps.yyx)
                         )
                     );
}


// why not put the raymarcher in a separate function (;
vec3 raymarch(vec3 ro, vec3 rd, float steps) {

    float mat = 0.,
          t   = 0.,
          d   = 0.;
    vec3 p = ro;
    for(float i=.0; i<steps; i++) {

        d = map(p);
        mat = g_mat;  // save global material

        if(abs(d) < 0.0001 || t > 100.) break;

        t += d;
        p += rd*d;
    }

    //g_p = p;

    return vec3(t, mat, t);
}

// thanks to iq!!
float softshadow( in vec3 ro, in vec3 rd, in float mint, in float tmax )
{
	float res = 1.0;
    float t = mint;
    for( int i=0; i<1; i++ )
    {
		float h = map( ro + rd*t );
        res = min( res, 8.0*h/t );
        t += h*.25;
        if( h<0.001 || t>tmax ) break;
    }
    return clamp( res, 0., 1. );
}

float calcAO(vec3 p, vec3 n)
{
	float sca = 2.0, occ = 0.0;
    for( int i=0; i<5; i++ ){

        float hr = 0.01 + float(i)*0.5/4.0;        
        float dd = map(n * hr + p);
        occ += (hr - dd)*sca;
        sca *= 0.7;
    }
    return clamp( 1.0 - occ, 0.0, 1.0 );    
}


vec3 getRayDir(vec2 uv, vec3 p, vec3 l, float z) {

    // camera system
    vec3 f = normalize(l - p),  // forward vector
         r = normalize(cross(vec3(0, 1, 0), f)), // right vector
         u = cross(f, r), // up vector
         c = p + f * z, // center of virtual screen
         i = c + uv.x * r + uv.y * u, // intersection with screen
         rd = normalize(i - p);  // ray direction

    return rd;

}

// Shane awesome work below
// Tri-Planar blending function. Based on an old Nvidia tutorial.
vec3 tex3D( sampler2D tex, in vec3 p, in vec3 n ){

    //return cellTileColor(p);

    n = max((abs(n) - 0.2)*7., 0.001); // n = max(abs(n), 0.001), etc.
    n /= (n.x + n.y + n.z ); 
	return (texture(tex, p.yz)*n.x + texture(tex, p.zx)*n.y + texture(tex, p.xy)*n.z).xyz;
}


// Texture bump mapping. Four tri-planar lookups, or 12 texture lookups in total. I tried to 
// make it as concise as possible. Whether that translates to speed, or not, I couldn't say.
vec3 texBump( sampler2D tx, in vec3 p, in vec3 n, float bf){

    const vec2 e = vec2(0.002, 0);

    // Three gradient vectors rolled into a matrix, constructed with offset greyscale texture values.    
    mat3 m = mat3( tex3D(tx, p - e.xyy, n), tex3D(tx, p - e.yxy, n), tex3D(tx, p - e.yyx, n));

    vec3 coeffs = vec3(0.299*SIN(tt), 0.587, 0.114*SIN(.7*tt));
    vec3 g = coeffs*m; // Converting to greyscale.
    g = (g - dot(tex3D(tx,  p , n), coeffs) )/e.x; g -= n*dot(n, g);

    return normalize( n + g*bf ); // Bumped normal. "bf" - bump factor.

}

