vec4 subsurface(vec3 o, vec3 dir){
    vec3 p = o;
    float e = 0.0;
    for(int i = 0; i < 7; ++i){
        float d = map(p);
        e += -d;
        if(d > -0.001)
            break;
        p -= d*dir;
    }

    return vec4(p, e);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   	vec2 uv = (fragCoord - .5*iResolution.xy)/iResolution.y;

    //uv = uv.yx;
  //  uv.xy = abs(uv.xy);
    tt = iTime;
    float zoom = 9.;// mix(4., 9., SIN(.4*iTime));
    vec3  lp = vec3(5., 2.*sin(tt*.5), -7.),
          lp2 = vec3(-5., -1, -8.);

    vec3 col = vec3(0);

    float px = -.0*tt;
    ro = vec3(px, -8.  - SIN(.5*tt)*10., -12. + SIN(tt)*3.);
    vec3 lookat = vec3(px, 0, 0), p;

    cam(ro);

    vec3 rd = getRayDir(uv, ro, lookat, 1.5);

    float mat = 0.,
          t   = 0.,
          d   = 0.;



    vec2 e = vec2(0.0035, -0.0035);


    // light color
    vec3 lc1 = vec3(0.702,1.000,0.965);
    vec3 lc2 = vec3(1.000,0.929,0.678);


    // currently only one pass
    for(float i = 0.; i < 1.; i++) {
        float steps = i > 0. ? 50. : 120.;
        vec3 rm = raymarch(ro, rd, steps);

        mat = rm.y;
        vec3 pp = g_p;

        vec3 p = ro + rm.x*rd;
        vec3 n = normalize( e.xyy*map(p+e.xyy) + e.yyx*map(p+e.yyx) +
                            e.yxy*map(p+e.yxy) + e.xxx*map(p+e.xxx));


        n = texBump(iChannel1, pp*2., n, .05);
        if(rm.x < 50.) {

            vec3 l = normalize(lp-p);
            vec3 l2 = normalize(lp2-p);
            float dif = max(dot(n, l), .0);
            float dif2 = max(dot(n, l2), .0);
            float spe = pow(max(dot(reflect(-rd, n), -l), .0),40.);

            // Fresnel
            float fre = pow(clamp(1.0 + dot(n, rd), 0.0, 1.0), 2.0);

            float sss = smoothstep(0., 1., map(p + l * .4)) / .4;
            float sss2 = smoothstep(0., 1., map(p + l2 * .4)) / .4;

            // subsurface scattering
            vec3 h = normalize(mix(-n, rd, 0.5));
            // sv.zyz contains outgoing position, w contains accumulate distance (path "tightness")
            vec4 sv = subsurface(p+h*0.02, rd);
            // subsurface magic term
            float sss3 = max(0.0, 1.0-2.0*sv.w);

            float difO = dif;
            dif = mix(dif, sss3, 0.5);
            dif2 = mix(dif2, sss3, 0.5);

            vec3 light = .5*(dif*lc1 + dif2*lc2);

            col = light*getColorRamp(PAL, .1*dif-length(p)*0.05-length(pp)*.5*mix(.0, 1., SIN(.5*tt))+.5*tt + smoothNoise21(p.xz*.4)*.15 + p.z*.1)*1.;

            col = mix(col, col*S(-4., 2., pp.y), .5);
              float ao = calcAO(p, n);

            col = mix(col, col*(1.-ao), .3);

            rd = reflect(rd, n);
            vec3 refl = texture(iChannel0, rd).bbb;


            refl = pow(refl, vec3(1./1.5));
            col = mix(col, 1.5*col*refl.rgb, .2);
            float t= rm.x;

            float fog = exp(-t*t*0.04);
            col = mix(col, vec3(0), fog);
            // gcol = mix(gcol, al, .2);

        } 
    }


    col += mix(-NOISE_GRANULARITY, NOISE_GRANULARITY, random(uv));
    col *= mix(.2, 1., (1.5-pow(dot(uv, uv), .5))); // vignette

    col = pow(col*1.8, vec3(2.3));

    col = tanh(col*1.4);
    col = gamma(col); // gamma

    fragColor = vec4(col, 1.);
}

